mapper.select:
SELECT DISTINCT a.*
FROM public.mm_asset a
LEFT JOIN public.mm_asset_text t ON t.asset_id = a.asset_id
LEFT JOIN public.mm_asset_tag atg ON atg.asset_id = a.asset_id
LEFT JOIN public.mm_tag tg ON tg.tag_id = atg.tag_id
LEFT JOIN public.mm_asset_category ac ON ac.asset_id = a.asset_id
LEFT JOIN public.mm_category c ON c.category_id = ac.category_id
WHERE a.dataset_version_id = #{datasetVersionId}

  AND (a.file_name ILIKE CONCAT('%', #{keyword}, '%') OR t.content ILIKE CONCAT('%', #{keyword}, '%'))


  AND tg.tag_name = #{tagName}


  AND c.category_name = #{categoryName}

ORDER BY a.created_at DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(DISTINCT a.asset_id) FROM public.mm_asset a LEFT JOIN public.mm_asset_text t ON t.asset_id = a.asset_id LEFT JOIN public.mm_asset_tag atg ON atg.asset_id = a.asset_id LEFT JOIN public.mm_tag tg ON tg.tag_id = atg.tag_id LEFT JOIN public.mm_asset_category ac ON ac.asset_id = a.asset_id LEFT JOIN public.mm_category c ON c.category_id = ac.category_id WHERE a.dataset_version_id = #{datasetVersionId}
AND (a.file_name ILIKE CONCAT('%', #{keyword}, '%') OR t.content ILIKE CONCAT('%', #{keyword}, '%'))
AND tg.tag_name = #{tagName}
AND c.category_name = #{categoryName}

WITH existing AS (
    SELECT tag_id FROM public.mm_tag WHERE space_id = #{spaceId} AND tag_name = #{tagName}
), inserted AS (
    INSERT INTO public.mm_tag (tag_id, space_id, tag_name, created_by)
    SELECT gen_random_uuid(), #{spaceId}, #{tagName}, #{createdBy}
    WHERE NOT EXISTS (SELECT 1 FROM existing)
    RETURNING tag_id
)
SELECT tag_id FROM inserted
UNION ALL
SELECT tag_id FROM existing
LIMIT 1
